  'help.type.cant_login': 'Tak boleh log masuk',
  'help.type.email_issue': 'Masalah dengan email',
  'help.type.security': 'Keselamatan',
  'help.type.other': 'Lain-lain',
  'help.faq.cantLogin.q': 'Tak boleh akses akaun saya',
  'help.faq.cantLogin.a': 'Semak jika anda menggunakan email dan kata laluan yang betul. Jika terlupa kata laluan, klik "Terlupa kata laluan?" di skrin log masuk. Jika masalah berterusan, buat tiket sokongan.',
  'help.faq.notReceiving.q': 'Tak terima email',
  'help.faq.notReceiving.a': 'Semak folder Spam terlebih dahulu. Pastikan storan anda tidak penuh. Jika masalah berterusan, sahkan bahawa penghantar mempunyai alamat yang betul dan buat tiket.',
  'help.faq.cantSend.q': 'Tak boleh hantar email',
  'help.faq.cantSend.a': 'Semak sambungan internet anda dan jika alamat penerima adalah betul. Pastikan lampiran tidak melebihi 25MB. Cuba lagi dalam beberapa minit.',
  'help.faq.forgotPassword.q': 'Terlupa kata laluan',
  'help.faq.forgotPassword.a': 'Di skrin log masuk, klik "Terlupa kata laluan?" dan ikut arahan untuk menetapkan semula kata laluan anda melalui email pemulihan.',
  'help.faq.accountSecurity.q': 'Saya rasa akaun saya telah terjejas',
  'help.faq.accountSecurity.a': 'Tukar kata laluan anda dengan segera. Semak folder Dihantar untuk mesej yang anda tidak hantar. Aktifkan pengesahan dua langkah di Tetapan > Keselamatan. Jika perlu, buat tiket segera.',
  'help.faq.appAccess.q': 'Bagaimana cara akses app di telefon bimbit?',
  'help.faq.appAccess.a': 'Anda boleh akses Chatyy melalui pelayar di chatyy.com.br, atau muat turun app kami di kedai aplikasi peranti anda.',
  'privacy.title': 'Dasar Privasi',
  'privacy.subtitle': 'Bagaimana kami melindungi dan mengendalikan data anda',
  'privacy.lastUpdated': 'Kemaskini terakhir: Mac 2026',
  'privacy.dataCollection.title': 'Pengumpulan Data',
  'privacy.dataCollection.body': 'Kami hanya mengumpul maklumat yang diperlukan untuk perkhidmatan email: nama anda, alamat email dan kandungan mesej yang dihantar dan diterima. Kami tidak menjual atau berkongsi data peribadi anda dengan pihak ketiga untuk tujuan pemasaran.',
  'privacy.dataUsage.title': 'Bagaimana Kami Menggunakan Data Anda',
  'privacy.dataUsage.body': 'Data anda digunakan secara eksklusif untuk mengendalikan dan meningkatkan perkhidmatan email, termasuk penghantaran mesej, penapisan spam, ciri AI (dengan persetujuan anda) dan keselamatan akaun.',
  'privacy.dataSecurity.title': 'Keselamatan Data',
  'privacy.dataSecurity.body': 'Kami menggunakan penyulitan standard industri (TLS/SSL) untuk semua data dalam transit dan dalam simpanan. Sesi dilindungi dengan token yang disulitkan dan perlindungan CSRF. Kami sentiasa mengaudit amalan keselamatan kami.',
  'privacy.cookies.title': 'Cookies dan Penyimpanan Tempatan',
  'privacy.cookies.body': 'Kami menggunakan cookies penting dan penyimpanan tempatan untuk mengekalkan sesi anda, mengingat pilihan anda (tema, bahasa) dan memberikan pengalaman yang lancar. Kami tidak menggunakan cookies penjejakan pihak ketiga.',
  'privacy.thirdParties.title': 'Perkhidmatan Pihak Ketiga',
  'privacy.thirdParties.body': 'Kami mungkin menggunakan perkhidmatan pihak ketiga untuk fungsi tertentu seperti AI (Anthropic Claude) dan pemberitahuan push. Perkhidmatan ini mengikuti dasar privasi mereka sendiri dan hanya memproses data minimum yang diperlukan.',
  'privacy.rights.title': 'Hak Anda',
  'privacy.rights.body': 'Anda berhak untuk mengakses, membetulkan, mengeksport atau memadam data peribadi anda pada bila-bila masa. Anda boleh mengurus data anda di Tetapan atau menghubungi sokongan kami.',
  'privacy.contact.title': 'Hubungi Kami',
  'privacy.contact.body': 'Untuk pertanyaan privasi atau permintaan data, hubungi melalui privacy@chatyy.com.br. Kami akan membalas dalam masa 30 hari.',
  'terms.title': 'Terma Perkhidmatan',
  'terms.subtitle': 'Garis panduan penggunaan Chatyy',
  'terms.lastUpdated': 'Kemaskini terakhir: Mac 2026',
  'terms.acceptance.title': 'Penerimaan Terma',
  'terms.acceptance.body': 'Dengan mengakses atau menggunakan Chatyy, anda bersetuju dengan Terma Perkhidmatan ini. Jika anda tidak bersetuju dengan mana-mana bahagian terma ini, jangan gunakan perkhidmatan ini.',
  'terms.services.title': 'Penerangan Perkhidmatan',
  'terms.services.body': 'Chatyy menyediakan perkhidmatan komunikasi melalui email termasuk penghantaran, penerimaan dan pengurusan email, serta ciri AI, integrasi dengan kalendar dan videoconferencing.',
  'terms.accounts.title': 'Akaun Pengguna',
  'terms.accounts.body': 'Anda bertanggungjawab untuk menjaga keselamatan kelayakan anda. Jangan kongsi kata laluan anda atau membenarkan akses tidak sah ke akaun anda. Anda mesti berumur sekurang-kurangnya 13 tahun untuk menggunakan perkhidmatan ini.',
  'terms.conduct.title': 'Penggunaan yang Diterima',
  'terms.conduct.body': 'Anda bersetuju untuk tidak menggunakan perkhidmatan untuk menghantar spam, malware, phishing atau sebarang kandungan haram. Jangan cuba mengakses akaun pengguna lain atau mengganggu infrastruktur perkhidmatan.',
  'terms.content.title': 'Kepemilikan Kandungan',
  'terms.content.body': 'Anda mengekalkan hak milik semua kandungan yang anda buat dan hantar melalui perkhidmatan. Kami tidak menuntut hak milik ke atas email atau lampiran anda. Kami boleh memproses kandungan seperti yang diperlukan untuk memberikan perkhidmatan.',
  'terms.limitation.title': 'Had Tanggungjawab',
  'terms.limitation.body': 'Chatyy disediakan "seadanya". Kami berusaha untuk 99.9% ketersediaan tetapi tidak menjamin perkhidmatan tanpa gangguan. Kami tidak bertanggungjawab atas kerosakan tidak langsung, insidental atau akibat yang timbul daripada penggunaan perkhidmatan.',
  'terms.termination.title': 'Penutupan Akaun',
  'terms.termination.body': 'Kami boleh menggantung atau menutup akaun yang melanggar terma ini. Anda boleh memadam akaun anda pada bila-bila masa di Tetapan. Setelah penutupan, data anda akan dipadam dalam masa 30 hari.',
  'terms.changes.title': 'Perubahan Terma',
  'terms.changes.body': 'Kami boleh mengemas kini terma ini secara berkala. Kami akan memaklumkan tentang perubahan penting melalui email atau pemberitahuan dalam app. Penggunaan berterusan selepas perubahan merupakan penerimaan terma yang dikemas kini.',
