  'plans.storageWarning': 'Anda menggunakan {used} dari {total}',
  'plans.storageWarningUpgrade': 'Tingkatkan ke Chatyy One dan dapatkan 200 GB!',
  'plans.faqWhatIsPlus': 'Apa itu Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Ia adalah pelan premium Chatyy yang melindungi semua perbualan, foto, dan video anda. Dengan Chatyy One, walaupun anda memadam sesuatu secara tidak sengaja, anda boleh memulihkannya dalam masa 30 hari. Selain itu, anda mendapat 200GB penyimpanan, One AI sebagai pembantu peribadi, dan boleh menghantar fail sehingga 100MB.',
  'plans.faqCancelAnswer': 'Pelan anda terus aktif sehingga akhir tempoh yang dibayar. Selepas itu, anda kembali ke pelan percuma. Foto dan video anda yang melebihi 15GB akan disimpan selama 30 hari lagi untuk anda muat turun.',
  'plans.faqHowFamily': 'Bagaimana pelan Pro berfungsi?',
  'plans.faqHowFamilyAnswer': 'Anda boleh menambah sehingga 4 orang dari keluarga anda. Semua berkongsi 500GB penyimpanan dan menerima semua manfaat dari Chatyy One. Setiap orang mempunyai ruang peribadi mereka — tiada siapa melihat fail orang lain.',
  'plans.faqChangePlanAnswer': 'Ya! Jika anda menaik taraf dari Plus ke Pro, hanya perbezaan yang akan dikenakan. Jika anda menurunkan taraf, pelan semasa akan terus sehingga akhir tempoh.',
  'plans.faqCardDeclined': 'Kad saya ditolak, apa yang perlu saya lakukan?',
  'plans.faqCardDeclinedAnswer': 'Anda mempunyai 7 hari untuk mengemas kini kad anda. Dalam tempoh ini, semua manfaat anda akan terus berfungsi. Selepas 7 hari, pelan akan kembali ke percuma.',
  'plans.faqDataSafe': 'Adakah data saya selamat?',
  'plans.faqDataSafeAnswer': 'Ya! Data pembayaran anda diproses dengan penyulitan hujung ke hujung. Kami tidak menyimpan nombor kad anda — hanya 4 digit terakhir untuk rujukan anda.',
